import Foundation

/// Pure decision logic for the opt-in developer clipboard history. No pasteboard or UI access, so it is unit-testable.
public enum ClipboardFilter {
    public static let maxBytes = 256 * 1024
    public static let minimumConfidence = 0.6

    /// Pasteboard types that mark an item as secret, transient or machine-generated (nspasteboard.org convention).
    public static let privateTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
    ]

    public enum Skip: Sendable, Equatable {
        case privateType, excludedApp, notText, empty, tooLarge, notDeveloperFormat
    }

    public enum Decision: Sendable, Equatable {
        case keep(toolID: String, reason: String)
        case skip(Skip)

        public var isKept: Bool { if case .keep = self { return true } else { return false } }
    }

    /// - Parameters:
    ///   - text: the pasteboard's plain string, or nil when the item has no text.
    ///   - sourceBundleID: bundle id of the frontmost app when the change was seen.
    ///   - types: raw pasteboard type identifiers present on the item.
    public static func evaluate(text: String?, sourceBundleID: String?, types: [String],
                                excludedApps: Set<String>, tools: [AnyTool]) -> Decision {
        if types.contains(where: privateTypes.contains) { return .skip(.privateType) }
        if let id = sourceBundleID, excludedApps.contains(id) { return .skip(.excludedApp) }
        guard let text else { return .skip(.notText) }
        if text.utf8.count > maxBytes { return .skip(.tooLarge) }
        if text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty { return .skip(.empty) }
        let report = DetectionEngine.detect(text, tools: tools, minimumConfidence: minimumConfidence)
        guard let best = report.best else { return .skip(.notDeveloperFormat) }
        return .keep(toolID: best.tool.id, reason: best.score.reason)
    }
}
